KEYS = {'sstv_auto_save': {'en': 'Automatically save received images', 'it': 'Salva automaticamente le immagini ricevute', 'fr': 'Enregistrer automatiquement les images reçues', 'de': 'Empfangene Bilder automatisch speichern', 'no': 'Lagre mottatte bilder automatisk', 'cs': 'Automaticky ukládat přijaté obrázky'}, 'sstv_choose_folder': {'en': 'Choose received-image folder', 'it': 'Scegli cartella immagini ricevute', 'fr': 'Choisir le dossier des images reçues', 'de': 'Ordner für Empfangsbilder wählen', 'no': 'Velg mappe for mottatte bilder', 'cs': 'Vybrat složku přijatých obrázků'}, 'sstv_open_folder': {'en': 'Open received-image folder', 'it': 'Apri cartella ricevute', 'fr': 'Ouvrir le dossier des images reçues', 'de': 'Ordner der Empfangsbilder öffnen', 'no': 'Åpne mappe med mottatte bilder', 'cs': 'Otevřít složku přijatých obrázků'}, 'sstv_save_off': {'en': 'Automatic saving is off.', 'it': 'Salvataggio automatico disattivato.', 'fr': 'Enregistrement automatique désactivé.', 'de': 'Automatisches Speichern ausgeschaltet.', 'no': 'Automatisk lagring er av.', 'cs': 'Automatické ukládání je vypnuté.'}, 'sstv_save_ready': {'en': 'Ready to save completed images.', 'it': 'Pronto a salvare le immagini completate.', 'fr': 'Prêt à enregistrer les images terminées.', 'de': 'Bereit zum Speichern vollständiger Bilder.', 'no': 'Klar til å lagre ferdige bilder.', 'cs': 'Připraveno ukládat dokončené obrázky.'}, 'sstv_save_pending': {'en': 'Saving received image...', 'it': 'Salvataggio immagine ricevuta...', 'fr': 'Enregistrement de l’image reçue...', 'de': 'Empfangenes Bild wird gespeichert...', 'no': 'Lagrer mottatt bilde...', 'cs': 'Ukládání přijatého obrázku...'}, 'sstv_saved': {'en': 'Saved: %1', 'it': 'Salvata: %1', 'fr': 'Enregistrée : %1', 'de': 'Gespeichert: %1', 'no': 'Lagret: %1', 'cs': 'Uloženo: %1'}, 'sstv_save_failed': {'en': 'Image not saved: %1', 'it': 'Immagine non salvata: %1', 'fr': 'Image non enregistrée : %1', 'de': 'Bild nicht gespeichert: %1', 'no': 'Bildet ble ikke lagret: %1', 'cs': 'Obrázek nebyl uložen: %1'}, 'sstv_folder_pending': {'en': 'The folder is created when the first image is saved.', 'it': 'La cartella viene creata al primo salvataggio.', 'fr': 'Le dossier est créé au premier enregistrement.', 'de': 'Der Ordner wird beim ersten Speichern erstellt.', 'no': 'Mappen opprettes når det første bildet lagres.', 'cs': 'Složka se vytvoří při prvním uložení.'}, 'sstv_folder_open_failed': {'en': 'Unable to open the received-image folder.', 'it': 'Impossibile aprire la cartella delle immagini ricevute.', 'fr': 'Impossible d’ouvrir le dossier des images reçues.', 'de': 'Der Ordner der Empfangsbilder kann nicht geöffnet werden.', 'no': 'Kan ikke åpne mappen med mottatte bilder.', 'cs': 'Složku přijatých obrázků nelze otevřít.'}}
HELP = {'en': ('Save received SSTV images automatically', 'In Mode, enable Automatically save received images and choose the destination with the folder button. The preference and folder are remembered. By default the option is off; the proposed directory is Pictures/MadModem/SSTV, created on the first save. Completed live or WAV images are written as PNG in the background. Names contain UTC date/time and mode, for example 2026-10-26_183045_Robot36.png; numeric suffixes preserve existing files. The saved pixels are those at completion, including adjustments active then. Later adjustments use Save PNG for a new manual export. Open received-image folder launches the file manager. Success or failure appears in the receive status and runtime log. Accepted jobs keep their original destination even if the option or folder changes, and finish at program close. Received images never replace your own QSL or enter the TX editor.'), 'it': ('Salvataggio automatico delle immagini SSTV ricevute', 'Nella scheda Modo attiva Salva automaticamente le immagini ricevute e scegli la destinazione con il pulsante della cartella. Opzione e percorso restano memorizzati. La funzione parte disattivata; la cartella proposta è Immagini/MadModem/SSTV e viene creata al primo salvataggio. Le immagini completate, da RX o WAV, vengono scritte in PNG in background. I nomi contengono data e ora UTC e modo, per esempio 2026-10-26_183045_Robot36.png; un suffisso numerico conserva i file già esistenti. Si salvano i pixel presenti al completamento, comprese le regolazioni attive in quel momento. Per regolazioni successive usa Salva PNG come esportazione manuale. Apri cartella ricevute apre il gestore dei file. Esito ed eventuali errori appaiono nello stato RX e nel registro. I salvataggi già accettati mantengono la destinazione iniziale anche cambiando opzione o cartella e vengono completati alla chiusura. Le immagini ricevute restano separate dalla tua QSL e dall’editor TX.'), 'fr': ('Enregistrer automatiquement les images SSTV reçues', 'Dans Mode, activez l’enregistrement automatique et choisissez le dossier. L’option et le chemin sont mémorisés. Par défaut, l’option est désactivée et le dossier proposé est Images/MadModem/SSTV, créé au premier enregistrement. Les images terminées, reçues en direct ou depuis un WAV, sont enregistrées en PNG en arrière-plan. Le nom contient la date et l’heure UTC et le mode ; un suffixe numérique préserve les fichiers existants. Les pixels enregistrés sont ceux de la fin de réception, avec les réglages actifs. Pour une correction ultérieure, utilisez Enregistrer PNG. Ouvrir le dossier lance le gestionnaire de fichiers. L’état RX et le journal indiquent le résultat. Les tâches déjà acceptées conservent leur dossier et se terminent à la fermeture. Les images reçues restent séparées de votre QSL et de l’éditeur TX.'), 'de': ('Empfangene SSTV-Bilder automatisch speichern', 'Im Modus-Reiter das automatische Speichern einschalten und den Zielordner wählen. Option und Pfad bleiben gespeichert. Die Option ist zunächst aus; vorgeschlagen wird Bilder/MadModem/SSTV, beim ersten Speichern angelegt. Vollständige Live- und WAV-Bilder werden im Hintergrund als PNG gespeichert. Dateinamen enthalten UTC-Datum, Uhrzeit und Modus; numerische Zusätze erhalten vorhandene Dateien. Gespeichert werden die Pixel bei Bildabschluss mit den dann aktiven Anpassungen. Spätere Änderungen mit PNG speichern exportieren. Ordner öffnen startet den Dateimanager. Empfangsstatus und Protokoll zeigen Erfolg oder Fehler. Bereits angenommene Aufträge behalten ihren Zielordner und werden beim Beenden abgeschlossen. Empfangsbilder bleiben von der eigenen QSL und dem TX-Editor getrennt.'), 'no': ('Lagre mottatte SSTV-bilder automatisk', 'Aktiver automatisk lagring i Modus og velg målmappe. Valg og mappe huskes. Valget er av som standard; foreslått mappe er Bilder/MadModem/SSTV, opprettet ved første lagring. Ferdige live- og WAV-bilder lagres som PNG i bakgrunnen. Navnet inneholder UTC-dato, tid og modus; talltillegg beskytter eksisterende filer. Pikslene ved fullført mottak lagres, med justeringene som da var aktive. Bruk Lagre PNG for senere justeringer. Åpne mappe starter filbehandleren. RX-status og logg viser resultatet. Allerede godtatte jobber beholder målmappen og fullføres ved avslutning. Mottatte bilder holdes atskilt fra eget QSL-kort og TX-redigering.'), 'cs': ('Automaticky ukládat přijaté obrázky SSTV', 'Na kartě Režim zapněte automatické ukládání a vyberte cílovou složku. Nastavení a cesta se pamatují. Volba je zpočátku vypnutá; navržená složka Obrázky/MadModem/SSTV se vytvoří při prvním uložení. Dokončené živé i WAV obrázky se ukládají na pozadí do PNG. Název obsahuje datum a čas UTC a režim; číselná přípona chrání existující soubory. Uloží se pixely při dokončení příjmu včetně tehdy aktivních úprav. Pozdější úpravy exportujte přes Uložit PNG. Otevřít složku spustí správce souborů. Výsledek ukáže stav RX a protokol. Přijaté úlohy si ponechají cílovou složku a dokončí se při zavření programu. Přijaté obrázky zůstávají oddělené od vlastní QSL a editoru TX.')}
